config.script:
// Build the identity pieces the form needs.
// identity.* and addresses.0.* come from the scrolls SDK runtime.
// Domain comes from the identity email when present, else outlook.com.
var email = ("{{identity.email}}" || "").trim();
var local = email.indexOf("@") > 0 ? email.split("@")[0] : email;
var dom = (email.indexOf("@hotmail.com") !== -1) ? "hotmail.com" : "outlook.com";
var dob = "{{identity.dob}}";
var y = "", m = "", d = "";
var mm = dob.match(/(\d{4})[-\/\.](\d{1,2})[-\/\.](\d{1,2})/);
if (mm) { y = mm[1]; m = String(parseInt(mm[2], 10)); d = String(parseInt(mm[3], 10)); }
else {
  var m2 = dob.match(/(\d{1,2})[-\/\.](\d{1,2})[-\/\.](\d{4})/);
  if (m2) { d = String(parseInt(m2[1], 10)); m = String(parseInt(m2[2], 10)); y = m2[3]; }
}
if (!y) { y = "1995"; m = "6"; d = "15"; }
var months = ["January","February","March","April","May","June","July","August","September","October","November","December"];
var monthName = months[Math.min(11, Math.max(0, parseInt(m, 10) - 1))];
var year = parseInt(y, 10); if (year > 2010) year = 1995;
return {
  emailLocal: local,
  fullEmail: local + "@" + dom,
  msDomain: "@" + dom,
  domainText: dom === "hotmail.com" ? "hotmail.com" : "outlook.com",
  month: monthName,
  day: d,
  year: String(year),
  country: ("{{addresses.0.country}}" || "").trim()
};

// Email-step gate. The signup page always puts "account" in its
// <title> from first paint, so the title is the fast reliable page-loaded
// signal; the fill step's own long timeout absorbs slow form render. When the
// title never lands we THROW with a diagnostic (real title, url, readyState,
// a body snippet) so the log shows WHAT the page actually is - a block page,
// a redirect, a blank shell - instead of a bare timeout. One in-page reload,
// then the throw rotates the exit (or just fails on direct connect).
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var tries = Number("{{gateTries}}") || 0;
var deadline = Date.now() + 45000;
while (Date.now() < deadline) {
  if ((document.title || "").toLowerCase().indexOf("account") !== -1) return { state: "ready", flow: "", tries: 0 };
  var body = (document.body && (document.body.innerText || ""));
  if (/unusual activity|temporarily blocked|try again later|verify your identity/i.test(body)) throw new Error("Microsoft served a block page - rotate the exit IP");
  await sleep(500);
}
if (tries >= 1) {
  var t = (document.title || "").slice(0, 80);
  var u = "";
  try { u = location.href.slice(0, 80); } catch (e) {}
  var rs = document.readyState;
  var snip = ((document.body && document.body.innerText) || "").replace(/\s+/g, " ").slice(0, 120);
  throw new Error("signup.live.com never loaded its account page. title='" + t + "' readyState=" + rs + " url=" + u + " body=" + snip);
}
return { state: "reload", flow: "", tries: tries + 1 };

// Resolve which email input actually exists once the page settles.
// signup.live.com redirects/re-renders after first paint, so a fixed
// comma-selector fill can time out waiting on a node that flashed and went.
// Wait for a stable input, then hand the fill step the exact selector.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
var deadline = Date.now() + 90000;
var lastUrl = "";
while (Date.now() < deadline) {
  var legacy = document.querySelector("#MemberName");
  var modern = document.querySelector("#usernameInput");
  if (vis(legacy)) return "input#MemberName";
  if (vis(modern)) return "input#usernameInput";
  try { lastUrl = location.href; } catch (e) {}
  // bounced to a sign-in page instead of signup - wrong landing
  if (/login\.live\.com|login\.microsoftonline\.com/i.test(lastUrl)) throw new Error("signup.live.com redirected to a sign-in page (" + lastUrl.slice(0, 70) + ") - exit IP is being deflected");
  await sleep(400);
}
var t = (document.title || "").slice(0, 60);
throw new Error("email input never became visible. title='" + t + "' url=" + lastUrl.slice(0, 70));

// Domain select only exists on one variant each (legacy: #LiveDomainBoxList,
// modern: #domainSelect). Pick the option whose label is the wanted domain.
var want = "{{msDomain}}";
var sel = document.querySelector("#LiveDomainBoxList") || document.querySelector("#domainSelect");
if (sel) {
  var done = false;
  for (var i = 0; i < sel.options.length; i++) {
    var t = (sel.options[i].text || "").toLowerCase();
    if (t.indexOf(want.replace("@", "")) !== -1) { sel.selectedIndex = i; sel.dispatchEvent(new Event("change", { bubbles: true })); done = true; break; }
  }
  return done ? "set" : "missing-option";
}
return "no-select";

// Scan for #usernameInputError across 3 passes, 2s apart.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
for (var pass = 0; pass < 3; pass++) {
  var els = document.querySelectorAll("#usernameInputError, #MemberNameError, [id$='InputError']");
  for (var i = 0; i < els.length; i++) {
    if (vis(els[i]) && (els[i].textContent || "").trim()) return "taken:" + (els[i].textContent || "").trim().slice(0, 160);
  }
  var pw = document.querySelector("#PasswordInput, #Password");
  if (vis(pw)) return "ok";
  await sleep(2000);
}
var pw2 = document.querySelector("#PasswordInput, #Password");
return vis(pw2) ? "ok" : "unknown";

// Wrap fetch/XHR before the challenge loads and stash data[blob] off the
// Arkose POST body ourselves.
if (!window.__scBlobHooked) {
  window.__scBlobHooked = true;
  window.__arkoseBlob = "";
  var pick = function (body) {
    if (!body) return "";
    try {
      var s = typeof body === "string" ? body : "";
      var m = s.match(/data%5Bblob%5D=([^&]+)/) || s.match(/data\[blob\]=([^&]+)/);
      return m ? decodeURIComponent(m[1]) : "";
    } catch (e) { return ""; }
  };
  var of = window.fetch;
  window.fetch = function (url, opts) {
    try {
      if (String(url).indexOf("client-api.arkoselabs.com/fc/gt2/public_key/") !== -1) {
        var b = pick(opts && opts.body);
        if (b) window.__arkoseBlob = b;
      }
    } catch (e) {}
    return of.apply(this, arguments);
  };
  var oo = XMLHttpRequest.prototype.open, os = XMLHttpRequest.prototype.send;
  XMLHttpRequest.prototype.open = function (m, u) { this.__scUrl = u; return oo.apply(this, arguments); };
  XMLHttpRequest.prototype.send = function (body) {
    try {
      if (String(this.__scUrl).indexOf("client-api.arkoselabs.com/fc/gt2/public_key/") !== -1) {
        var b = pick(body);
        if (b) window.__arkoseBlob = b;
      }
    } catch (e) {}
    return os.apply(this, arguments);
  };
}
return "armed";

// Country dropdown (legacy #Country / modern #countryRegionDropdown). Pick by
// visible text; empty input leaves whatever Microsoft geolocated.
var want = ("{{countryPick}}" || "").trim();
if (!want) return "skipped";
var sel = document.querySelector("#Country") || document.querySelector("#countryRegionDropdown");
if (!sel) throw new Error("Country dropdown not found");
for (var i = 0; i < sel.options.length; i++) {
  if ((sel.options[i].text || "").trim().toLowerCase() === want.toLowerCase()) {
    sel.selectedIndex = i;
    sel.dispatchEvent(new Event("change", { bubbles: true }));
    return "set:" + want;
  }
}
throw new Error("Country option not found: " + want);

// DOB fields are text inputs on both variants; type like a human.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var parts = "{{dob}}".split("|");
function put(sel, val) {
  var el = document.querySelector(sel);
  if (!el) throw new Error("missing " + sel);
  el.focus();
  el.value = "";
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.value = val;
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.dispatchEvent(new Event("change", { bubbles: true }));
}
put("#BirthMonth", parts[0]);
await sleep(400 + Math.random() * 900);
put("#BirthDay", parts[1]);
await sleep(400 + Math.random() * 900);
put("#BirthYear", parts[2]);
return "set";

// Pre-captcha SMS gate (bail here) + captcha frame detection.
// 'landed' short-circuits: Microsoft sometimes skips the challenge entirely.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
var deadline = Date.now() + 30000;
while (Date.now() < deadline) {
  if ((document.body && (document.body.innerText || "")).indexOf("When you need to prove") !== -1) return "sms-gate";
  if (location.href.indexOf("account.microsoft.com") !== -1) return "landed";
  var f = document.querySelector("#enforcementFrame");
  if (vis(f)) return "captcha";
  var hip = document.querySelector("#hipEnforcementContainer, #pageContent");
  if (vis(hip) && document.querySelector("iframe[src*='arkoselabs'], iframe[src*='funcaptcha'], #enforcementFrame")) return "captcha";
  await sleep(500);
}
return "timeout";

// Give the challenge a moment to fire its key POST, then read the stash.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var deadline = Date.now() + 20000;
while (Date.now() < deadline) {
  if (window.__arkoseBlob) return window.__arkoseBlob;
  await sleep(400);
}
return "";

// Cross-frame trick: the enforcementFrame is cross-origin, so inject a
// submitter INTO it, then postMessage the token up to the page's own listener.
// No token = the challenge never appeared; nothing to submit, land will confirm.
var token = "{{captchaToken}}";
if (!token) return "skipped-no-challenge";
var enc = document.getElementById("enforcementFrame");
var posted = false;
try {
  var encWin = enc && (enc.contentWindow || enc);
  var encDoc = enc && (enc.contentDocument || (encWin && encWin.document));
  if (encDoc) {
    var s = encDoc.createElement("SCRIPT");
    s.textContent = "function CaptchaSubmit(token){ var j = JSON.stringify({ eventId:'challenge-complete', payload:{ sessionToken: token } }); parent.postMessage(j, '*'); }";
    encDoc.documentElement.appendChild(s);
    encWin.CaptchaSubmit(token);
    posted = true;
  }
} catch (e) { /* cross-origin: fall through to direct postMessage */ }
if (!posted) {
  var j = JSON.stringify({ eventId: "challenge-complete", payload: { sessionToken: token } });
  if (enc && enc.contentWindow) enc.contentWindow.postMessage(j, "*");
  window.postMessage(j, "*");
}
return posted ? "injected" : "posted";

// Wait for the redirect to account.microsoft.com; retry the token post every
// few seconds in case the first one raced the listener attaching. Empty token
// means the challenge never appeared - Microsoft let us straight through.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
var token = "{{captchaToken}}";
var j = token ? JSON.stringify({ eventId: "challenge-complete", payload: { sessionToken: token } }) : "";
var deadline = Date.now() + 120000;
while (Date.now() < deadline) {
  if (location.href.indexOf("account.microsoft.com") !== -1) return "landed";
  if (j) {
    var f = document.getElementById("enforcementFrame");
    if (!f) { await sleep(1000); continue; }
    try { if (f.contentWindow) f.contentWindow.postMessage(j, "*"); window.postMessage(j, "*"); } catch (e) {}
  }
  await sleep(3000);
}
throw new Error("Signup never completed - no redirect to account.microsoft.com");

// Privacy notice + Stay-signed-in prompts: click through whatever shows.
function sleep(ms){return new Promise(function(r){setTimeout(r,ms);});}
function vis(el){if(!el)return false;var r=el.getBoundingClientRect();var s=getComputedStyle(el);return r.width>1&&r.height>1&&s.visibility!=='hidden'&&s.display!=='none';}
var deadline = Date.now() + 20000;
while (Date.now() < deadline) {
  var hit = false;
  var btns = document.querySelectorAll("button, a[role='button'], input[type='submit']");
  for (var i = 0; i < btns.length; i++) {
    if (!vis(btns[i])) continue;
    var t = ((btns[i].innerText || btns[i].value || "")).trim();
    if (/^(accept|next|yes|ok|continue)$/i.test(t)) { btns[i].click(); hit = true; break; }
  }
  var stay = document.querySelector("#idBtn_Back, #kmsiCheckboxField + label, [name='DontShowAgain']");
  if (vis(stay)) { stay.click(); hit = true; }
  if (!hit) break;
  await sleep(1500);
}
return "done";
